class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


NOT_COVERED, COVERED, HAS_CAMERA = 0, 1, 2


def min_camera_cover(root_arr):
    root = build_tree(root_arr)
    cameras = [0]

    def dfs(node):
        if node is None:
            return COVERED
        left_state = dfs(node.left)
        right_state = dfs(node.right)
        if left_state == NOT_COVERED or right_state == NOT_COVERED:
            cameras[0] += 1
            return HAS_CAMERA
        if left_state == HAS_CAMERA or right_state == HAS_CAMERA:
            return COVERED
        return NOT_COVERED

    if dfs(root) == NOT_COVERED:
        cameras[0] += 1
    return cameras[0]

